const v22AuditPageBefore=PAGE.audit;PAGE.audit=()=>v22AuditPageBefore()+v22Back(v22Panel('V22互动与运营记录',v22Table(['时间 UTC','操作人','动作 / 对象','依据'],v22Rows('logs').slice().reverse().map(x=>[e(x.at),e(x.actor),e(x.action+' / '+x.object),e(x.reason)]))));
const v22LoginBefore=admin19Login;admin19Login=function(...args){const a=v22LoginBefore(...args);v22Ensure();if(db.v22){const s=ADMIN19.session;db.v22.sessions.push({id:v22Id('SESSION'),accountId:a.id,username:a.username,issuedAt:new Date(s.issuedAt).toISOString(),expiresAt:new Date(s.expiresAt).toISOString(),status:'有效'});save();}return a;};
const v22DropBefore=admin19Drop;admin19Drop=function(...args){const s=ADMIN19.session;if(db.v22&&s){const r=db.v22.sessions.find(x=>x.accountId===s.accountId&&x.issuedAt===new Date(s.issuedAt).toISOString());if(r&&r.status==='有效')r.status='已结束';}V22.site='';V22.from='';V22.to='';V22.editActivity='';return v22DropBefore(...args);};
function v22Refresh(){if(FE.mode==='admin')render();else feRender();}
function v22RunAction(action,id,data){
 if(action==='topicDiscover'){V22.filters={topic:data.topic};FE.category='全部';return feNavigate('discover');}
 if(action==='matchBook'){
  v22Vip();const m=v22Get('matches',id);demand(m.user===FE.user&&m.selected,'仅匹配发起人可预约');if(m.draft){const d=db.feDrafts.find(x=>x.id===m.draft);return feNavigate(d.order?'order':'pay',d.order||d.id);}demand(v22MatchCandidates(m).some(p=>p.id===m.selected),'候选或档期已失效');const p=feProducts(m.selected).find(p=>!p.c21Type&&p.price<=m.budget&&(!m.category||p.catRootId===m.category)&&(()=>{try{feCheckBooking(p,m.day,m.time,p.provider);return true;}catch{return false;}})());demand(p,'没有符合预算及档期的商品');V22.matchBooking=m.id;FE.side='buyer';feNavigate('booking',p.id);const form=document.querySelector('form[data-fe-form="booking"]');if(form){form.elements.start.value=m.day;form.elements.time.value=m.time;}return;
 }
 if(action==='exportEvents'){admin19Require();const {events}=v22Facts();const rows=[['时间UTC','行为','对象','用户','服务者','站点','来源'],...events.map(x=>[x.at,x.type,x.object,x.user,x.provider,x.stationId,x.source])];return c21DownloadReport(rows.map(r=>r.map(x=>'"'+String(x).replaceAll('"','""')+'"').join(',')).join('\n'),'V22_本地事件.csv');}
 if(action==='editActivity'){admin19Require(true);V22.editActivity=id;return render();}
 if(action==='previewActivity'){admin19Require(true);const a=v22Get('activities',id);return openModal('活动预览',`<div class="v22-back"><h2>${e(a.title)}</h2><p>${e(a.description)}</p>${v22Pill(a.phase)}<p>站点：${e(siteLabel(a.stationId))}</p><p>状态：${e(a.status)}；发布后从用户端活动入口查看。</p></div>`);}
 const out=v22Persist(()=>v22Command(action,id,data));
 if(action==='consult')return feNavigate('v22Consult',out);
 if(action==='roomCreate'||action==='roomJoin')return feNavigate('v22Room',out);
 if(action==='matchCreate'||action==='matchChoose')return feNavigate('v22Match',out);
 if(action==='roomExit')return feNavigate('v22Rooms');
 FE.flash='本地操作已保存';v22Refresh();
}
document.addEventListener('click',ev=>{const b=ev.target.closest?.('[data-v22-command]');if(!b||b.disabled)return;ev.preventDefault();try{v22RunAction(b.dataset.v22Command,b.dataset.id||'',JSON.parse(b.dataset.values||'{}'));}catch(err){if(FE.mode==='admin')toast(err.message,'error');else{FE.flash=err.message;feRender();}}});
document.addEventListener('submit',ev=>{const f=ev.target;if(!f.dataset.v22Form)return;ev.preventDefault();if(!f.reportValidity())return;const action=f.dataset.v22Form,id=f.dataset.id||'',data=Object.fromEntries(new FormData(f));try{
 if(action==='filters'){V22.filters=data;return feNavigate('discover');}
 if(action==='activitySave'){const [type,...parts]=String(data.targetRef||'').split('|');data.targetType=type;data.target=parts.join('|');}
 if(action==='materialSubmit'){demand(!V22.uploadError,V22.uploadError);data.voice=V22.upload;data.busy=V22.uploadBusy;}
 const out=v22Persist(()=>v22Command(action,id,data,f.dataset.backend==='true'));
 if(f.dataset.backend==='true'){V22.editActivity='';return render();}
 if(action==='matchCreate')return feNavigate('v22Match',out);if(action==='roomCreate')return feNavigate('v22Room',out);
 if(action==='report'){FE.flash='举报已提交，后台将按原举报流程处理。编号 '+out;return feRender();}
 V22.upload=null;FE.flash='本地操作已保存';feRender();
 }catch(err){const box=f.querySelector('.v22-error');if(box)box.textContent=err.message;}});
document.addEventListener('change',async ev=>{const input=ev.target;if(input.dataset.v22AdminFilter){V22[input.dataset.v22AdminFilter]=input.value;renderContent();return;}if(!input.hasAttribute('data-v22-upload'))return;const status=input.parentElement.querySelector('[data-v22-upload-status]'),file=input.files?.[0];V22.upload=null;V22.uploadError='';V22.uploadBusy=false;if(!file)return;const token={};V22.uploadToken=token;try{demand(file.size<=1024*1024&&file.type.startsWith('audio/'),'请选择1MB以内音频文件');V22.uploadBusy=true;status.textContent='正在读取和验证音频…';const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(new Error('文件读取失败'));r.readAsDataURL(file);});const audio=new Audio();await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(new Error('音频解码超时')),10000);audio.onloadedmetadata=()=>{clearTimeout(timer);Number.isFinite(audio.duration)&&audio.duration>0?resolve():reject(new Error('音频时长无效'));};audio.onerror=()=>{clearTimeout(timer);reject(new Error('浏览器无法解码该音频'));};audio.src=data;});if(V22.uploadToken!==token||!input.isConnected)return;V22.upload=data;status.textContent='已就绪：'+file.name+'，保存后仍需审核';}catch(err){V22.uploadError=err.message;status.textContent=err.message;}finally{if(V22.uploadToken===token)V22.uploadBusy=false;}});
const v22RenderBefore=feRender;feRender=function(){v22Ensure();v22RenderBefore();if(FE.mode!=='admin')document.title='伴屿 · PC / H5 陪伴原型 · V22';};
const v22ShellBefore=renderShell;renderShell=function(){v22ShellBefore();const foot=document.querySelector('#sidebar .side-footer small');if(foot){foot.setAttribute('data-admin-no-translate','1');foot.textContent='本地演示 · 第二十二版';}};
// Original order detail remains the handling entry; expose related indexes without bulk private text.
const v22DetailBefore=renderDetail;renderDetail=function(){const out=v22DetailBefore();if(drawerState?.type==='orders'&&admin19Bound()){const o=getBy('orders',drawerState.id);if(o&&v22Scope(o.stationId)){const body=document.querySelector('#drawerRoot .drawer-body');if(body)body.insertAdjacentHTML('beforeend',v22Back(v22Panel('V22关联互动记录',`<p>咨询：${e(db.v22.consults.filter(c=>c.user===o.buyer&&c.provider===o.provider&&c.stationId===o.stationId).map(c=>c.id+' · '+c.status).join('；')||'无')}</p><p>匹配：${e(db.v22.matches.filter(m=>m.order===o.id).map(m=>m.id).join('；')||'无')}</p><p>模拟会话：${e(db.v22.calls.filter(c=>c.order===o.id).map(c=>c.id+' · '+c.status+' · '+(c.issue||'无异常')+' · '+(c.issueStatus||'')).join('；')||'无')}</p><p>咨询为同站同双方记录索引，不表示每条咨询必然导致本订单；正文仅在关联举报案件核查时展示。</p>`)));}}return out;};
